%[text] # Loops and Iteration
%[text] To illustrate using loops to implement an incremental operation, and generating 2D plots, consider the following scenario:
%[text] How does compound interest grow your TSP account?
%[text] - 30 year old contributing the max: \\$23,500
%[text] - Each year they plan to make 5% return total investment
%[text] - How much would that investment be worth when they are 55? \
%[text] ## Manual Iteration
%[text] How much would you make the first year?
principal = 23500;
r = 0.05;
return_year1 = principal * r %[output:45aad395]
%[text] So how much to I have to invest in year two?
new_principal = principal + return_year1 %[output:1825cc6d]
%[text] And how much will you make in the second year?
return_year2 = new_principal * r %[output:1e395296]
%[text] And now we have yet more to invest in the third year
new_prince = new_principal + return_year2 %[output:94347d81]
return_year3 = new_principal * r %[output:72d759b9]
%[text] So we start to see a pattern
%[text] $P\[n+1\]=P\[n\](1+r)$
P0 = principal %[output:4466d9b5]
P1 = P0*(1+r) %[output:95e770d2]
P2 = P1*(1+r) %[output:8c1f9f6c]
P3 = P2*(1+r) %[output:76aff924]
P4 = P3*(1+r) %[output:875ab3c1]
P5 = P4*(1+r) %[output:9506a6c6]
%[text] Visualize with a plot:
figure(1);
clf(); %[output:5ca41901]
plot(30,P0, 'o') %[output:5ca41901]
hold("on") %[output:5ca41901]
plot(31, P1, 'o') %[output:5ca41901]
plot(32, P2, 'o') %[output:5ca41901]
plot(33, P3, 'o') %[output:5ca41901]
plot(34, P4, 'o') %[output:5ca41901]
plot(35, P5, 'o') %[output:5ca41901]
%[text] Labels with units!
xlabel("Age [years]") %[output:5ca41901]
ylabel("Principal [$]") %[output:5ca41901]
%[text] 
%[text] ## for Loop Iteration
%[text] ![](text:image:9cda)
%[text] Don't Repeat Yourself (DRY)!
figure() %[output:55135895]
clf() %[output:55135895]

principal = 23500;
plot(30, principal, 'o') %[output:55135895]
hold("on"); %[output:55135895]

for ii = 31:55
    rtn = principal * r;
    principal = principal + rtn;
    
    plot(ii, principal, 'o') %[output:55135895]
end

xlabel("Age [years]") %[output:55135895]
ylabel("Principal [$]") %[output:55135895]
grid("on") %[output:55135895]
%[text] ## Analytical Model
%[text] Compounded annual instert:
%[text] $A = P(1+r)^{t}$
P = 23500;
r = 0.05;
t = 25;

A = P*(1+r)^t %[output:1eb6f27e]
%[text] Compare that to our numerical solution
principal %[output:6ec49fef]
%[text] 

